-- ===== supabase/updates/20261203000300_rich_list_speed.sql =====
-- ===== idempotent copy of migrations/20261203000300_rich_list_speed.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 0300 · The minute job no longer stalls on the rich list
-- =============================================================================
-- On the live database rich_list_snapshot() took 30 seconds; run_due_jobs() holds its locks that long and every
-- request behind it ran into the statement timeout. Two causes, both removed here:
--   1. rich_list_snapshots is read by taken_at (latest snapshot, previous snapshot, pruning) but had only an index
--      on (entity_id, taken_at): every such read scanned eight days of snapshots.
--   2. player_rich_rank() rebuilt the whole rich list (every player and tycoon with all holdings) for one rank.
--      Rank missions call it per mission, per player, in the snapshot job and in every get_my_missions().
--      It now reads the rank from the latest snapshot (at most a few minutes old) and only computes it live while
--      there is no fresh snapshot.
-- Idempotent: runs unchanged as supabase/updates/20261203000300_rich_list_speed.sql.

create index if not exists rich_list_snapshots_taken_idx
  on public.rich_list_snapshots (taken_at desc, entity_kind, entity_id);

create or replace function public.player_rich_rank(p_player uuid)
returns integer
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_latest timestamptz;
  v_rank   integer;
  v_fresh  interval := make_interval(secs => 2 * 60 * greatest(1, public.config_double('richList', '{snapshotMinutes}', 5)));
begin
  select max(s.taken_at) into v_latest from public.rich_list_snapshots s;
  if v_latest is not null and v_latest > public.game_now() - v_fresh then
    select s.rank_all into v_rank from public.rich_list_snapshots s
     where s.taken_at = v_latest and s.entity_kind = 'player' and s.entity_id = p_player;
    if v_rank is not null then
      return v_rank;
    end if;
  end if;
  -- no fresh snapshot (first minutes of a database, a player who just signed up): compute it
  return (select e.rank_all from public.rich_list_entries() e where e.entity_kind = 'player' and e.entity_id = p_player);
end;
$$;
comment on function public.player_rich_rank(uuid) is
  'Internal: rank of a player on the rich list, from the latest snapshot when it is fresh, else computed.';
revoke all on function public.player_rich_rank(uuid) from public, anon, authenticated;
grant execute on function public.player_rich_rank(uuid) to service_role;

-- ===== supabase/updates/20261203000400_market_orders_only.sql =====
-- ===== idempotent copy of migrations/20261203000400_market_orders_only.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 0400 · Market orders only: limit orders are switched off (ADR-117)
-- =============================================================================
-- The owner removed limit orders from the game. The client no longer offers them; the server refuses them while
-- game_config.trading.limitOrders is false. Without the key (tests, older configs) they stay allowed, so the
-- matching engine and its tests are untouched and the feature can come back by flipping the switch.
-- Limit orders that are already resting stay in the book until they fill or are cancelled.
-- Idempotent: runs unchanged as supabase/updates/20261203000400_market_orders_only.sql.

create or replace function public.orders_market_only()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.type = 'limit' and new.source = 'player'
     and not public.config_boolean('trading', '{limitOrders}', true) then
    perform public.api_error('locked');
  end if;
  return new;
end;
$$;
comment on function public.orders_market_only() is
  'Trigger: refuses new limit orders of players while trading.limitOrders is false (ADR-117).';
revoke all on function public.orders_market_only() from public, anon, authenticated;

drop trigger if exists orders_market_only on public.orders;
create trigger orders_market_only before insert on public.orders
  for each row execute function public.orders_market_only();

-- Missions about limit orders are no longer handed out.
update public.mission_templates set is_active = false
 where metric in ('limit_orders_placed', 'limit_orders_filled') and is_active;

commit;
